      AND ((c.table_name = 'wardogs_ttk' AND c.row_key->>'weapon_name' IN ('A-91', 'AK74', 'AMP-9', 'BMR-308', 'Bushmaster M17S', 'Deagle', 'FAL', 'Galil', 'GGX 17', 'GGX 18', 'Judge', 'KH-2002', 'M1911', 'M249 SAW', 'M4', 'MK22', 'Mosin Nagant', 'MP5', 'PKM', 'PP-19 Vityaz', 'Scout Rifle TD', 'SKS', 'Super-45', 'SV98', 'SVD', 'T-21', 'Evo-3 Ultra', 'M14', 'PP-19 Bizon', 'TCX-SPR'))
