-- VERIFY (read-only): expect 491 rows for this part.
SELECT c.table_name, c.change_type, c.field, count(*) AS n
FROM game_data_changes c JOIN game_patches p ON p.id = c.patch_id
WHERE p.game_slug = 'wardogs' AND p.patch_key = 'season-2' AND c.note = 'Evo4Fun workbook, sheet dated 30/10/2026, Season 2 per operator, not matched to a patch by the sheet itself'
  AND ((c.table_name = 'wardogs_ttk' AND c.row_key->>'weapon_name' IN ('A-91', 'AK74', 'AMP-9', 'BMR-308', 'Bushmaster M17S', 'Deagle', 'FAL', 'Galil', 'GGX 17', 'GGX 18', 'Judge', 'KH-2002', 'M1911', 'M249 SAW', 'M4', 'MK22', 'Mosin Nagant', 'MP5', 'PKM', 'PP-19 Vityaz', 'Scout Rifle TD', 'SKS', 'Super-45', 'SV98', 'SVD', 'T-21', 'Evo-3 Ultra', 'M14', 'PP-19 Bizon', 'TCX-SPR'))
      OR (c.table_name = 'weapon_stats' AND c.row_key->>'name' IN ('TCX-SPR', 'PP-19 Bizon', 'M14', 'Evo-3 Ultra')))
GROUP BY c.table_name, c.change_type, c.field ORDER BY 1, 2, 3;
